<?php require __DIR__.'/includes/bootstrap.php'; if(current_user()) redirect(current_user()['role']==='admin'?'admin/index.php':'member/index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=trim($_POST['identity']??'');$s=$pdo->prepare('SELECT * FROM users WHERE (username=? OR email=?) AND is_active=1 LIMIT 1');$s->execute([$id,$id]);$user=$s->fetch();if($user&&password_verify($_POST['password']??'',$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'username'=>$user['username'],'role'=>$user['role']];redirect($user['role']==='admin'?'admin/index.php':'member/index.php');}$error='Invalid login details or inactive account.';}
